package main

import (
	"testing"
	"time"
)

func TestProbeNewClockStore(t *testing.T) {
	store, advance := newClockStore(time.Minute)
	if store == nil {
		t.Fatal("newClockStore returned a nil store")
	}
	store.Create("abc", "ada")
	advance(30 * time.Second)
	if _, err := store.Get("abc"); err != nil {
		t.Fatalf("under ttl Get: %v", err)
	}
	if got := store.Len(); got != 1 {
		t.Fatalf("Len under ttl = %d, want 1", got)
	}
	advance(2 * time.Minute)
	if _, err := store.Get("abc"); err == nil {
		t.Fatal("over ttl Get: err = nil, want an error")
	}
	if got := store.Len(); got != 0 {
		t.Fatalf("Len over ttl = %d, want 0", got)
	}
}
EOF
